/* ======================================================================
   追加分: 入庫区分が「車検」以外のデータ (受付13〜15)

   受付1〜12は入庫区分がすべて「車検」(=1)か未選択(=0)で、
   入庫区分によって挙動が変わる項目を確認できなかったため追加する。

     受付13 … 一般整備(入庫区分2) / 工程セット確定済み
     受付14 … 板金  (入庫区分3) / 工程セット確定済み
     受付15 … 一般整備(入庫区分2) / 工程セット未確定

   これで確認できるようになること:
     【No12/No13】工程セットコンボの中身が入庫区分ごとに変わること。
                  車検は2セット(車検コース/車検コース(簡易))、一般整備・板金は1セットずつ。
                  既定フラグ=1のものが最初に選択されていること。
     【No15/No25】工程セットごとに作業工程の数と名前が変わること。
                  車検は4工程、一般整備は3工程、板金は4工程。
     【No31】      入庫区分選択済み・工程セット未選択のパターンを車検以外でも確認できる(受付15)。

   入庫区分の番号は 共通データ.sql の名称管理(マスタ区分=101)に合わせている。
     1=車検 / 2=一般整備 / 3=板金
   ====================================================================== */

-- 工程セットのメイン行は、入庫区分と既定フラグから引く。
-- 工程管理番号を直接書かないのは、工程セットマスタの番号が環境ごとに違うため。
-- 見つからない場合(共通データ.sqlの工程セットマスタが未投入のDB)は工程セットを紐付けず、
-- 行は表示されるが「工程セット未確定」の扱いになる。
DECLARE @一般整備メイン int, @一般整備セット int, @一般整備工程 int;
DECLARE @板金メイン int, @板金セット int, @板金工程 int;

SELECT TOP 1 @一般整備メイン = [工程管理番号], @一般整備セット = [工程セット番号]
  FROM [dbo].[作業進捗工程管理]
 WHERE [作業工程番号] = 0 AND [削除フラグ] = 0 AND [入庫区分番号] = 2 AND [既定フラグ] = 1;

SELECT TOP 1 @一般整備工程 = [工程管理番号]
  FROM [dbo].[作業進捗工程管理]
 WHERE [作業工程番号] > 0 AND [削除フラグ] = 0 AND [工程セット番号] = @一般整備セット
 ORDER BY [作業順];

SELECT TOP 1 @板金メイン = [工程管理番号], @板金セット = [工程セット番号]
  FROM [dbo].[作業進捗工程管理]
 WHERE [作業工程番号] = 0 AND [削除フラグ] = 0 AND [入庫区分番号] = 3 AND [既定フラグ] = 1;

SELECT TOP 1 @板金工程 = [工程管理番号]
  FROM [dbo].[作業進捗工程管理]
 WHERE [作業工程番号] > 0 AND [削除フラグ] = 0 AND [工程セット番号] = @板金セット
 ORDER BY [作業順];

